export function validateESPImage(raw,chip,{bootFromROM=false}={}){
 if(!Object.hasOwn(ESP_BOARDS,chip))throw Error('Geçersiz ESP kartı.');const board=ESP_BOARDS[chip],bytes=new Uint8Array(raw);
 if(bytes.length<32||bytes.length>board.flash)throw Error('Firmware boyutu geçersiz; kartın Flash sınırını kontrol edin.');
 const candidates=bootFromROM?[board.imageOffset||0,0,0x1000]:[board.imageOffset||0];let offset=candidates.find(n=>bytes[n]===0xe9&&bytes[n+1]>=1&&bytes[n+1]<=16&&n+24<=bytes.length);
 if(offset===undefined)throw Error(bootFromROM?'Birleştirilmiş ESP flash .bin bekleniyor.':'0 adresinden başlayan ESP uygulama .bin bekleniyor.');
 const view=new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength);if(view.getUint16(offset+12,true)!==board.chipId)throw Error('Firmware hedefi seçili kartla eşleşmiyor.');
 let at=offset+24,xor=0xef;for(let i=0;i<bytes[offset+1];i++){if(at+8>bytes.length)throw Error('Firmware segment başlığı eksik.');const len=view.getUint32(at+4,true);if(len>board.flash||at+8+len>bytes.length)throw Error('Firmware segment verisi eksik.');for(let j=at+8;j<at+8+len;j++)xor^=bytes[j];at+=8+len;}
 const check=Math.ceil((at+1)/16)*16-1;if(check>=bytes.length||bytes[check]!==xor)throw Error('Firmware checksum doğrulaması başarısız.');
 return{bytes,chip,entry:view.getUint32(offset+4,true),bootFromROM,offset};
}
